using System; using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine; public static class Phase4A_CorrectVisualPhysicsIntegration { public static void Run(){try{var sc=EditorSceneManager.OpenScene("Assets/Scenes/147VR_MainScene.unity"); var table=GameObject.Find("Prefab_WPBSA_12Foot_Snooker"); if(table==null)throw new Exception("table missing"); table.transform.SetParent(null,true); table.transform.localScale=Vector3.one; table.transform.localRotation=Quaternion.identity; var bed=Find(table.transform,"Bed_Collider"); var visual=Find(table.transform,"147VR_Table_WPBSA_12ft_VISUAL_MAIN"); var surface=Find(table.transform,"TABLE SURFACE"); if(bed==null||visual==null||surface==null)throw new Exception("required transforms missing"); bed.localScale=Vector3.one; visual.localScale=Vector3.one; visual.localRotation=Quaternion.Euler(0,90,0); surface.localRotation=Quaternion.identity; PrefabUtility.RecordPrefabInstancePropertyModifications(bed); PrefabUtility.RecordPrefabInstancePropertyModifications(visual); PrefabUtility.RecordPrefabInstancePropertyModifications(surface); EditorSceneManager.MarkSceneDirty(sc); bool ok=EditorSceneManager.SaveScene(sc); Debug.Log($"[4A CORRECT INTEGRATION] save={ok} bedWorld={bed.lossyScale} visualWorld={visual.lossyScale} visualRot={visual.eulerAngles} surfaceRot={surface.eulerAngles}"); EditorApplication.Exit(ok?0:3);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(3);}} static Transform Find(Transform r,string n){foreach(var t in r.GetComponentsInChildren<Transform>(true))if(t.name==n)return t;return null;} }


